const rawInput = $input.first().json;
let rawBody = rawInput.body !== undefined ? rawInput.body : rawInput;
let body = {};
if (typeof rawBody === 'string') {
  try { body = JSON.parse(rawBody); } catch (e) { body = {}; }
} else if (typeof rawBody === 'object' && rawBody !== null) {
  body = rawBody;
}
const action = body.action || 'direct';

// Ping / Verbindungstest aus PWA-Einstellungen
if (action === 'ping' || action === 'test') {
  return {
    json: {
      is_login: true,
      status: 'success',
      message: '✓ Verbindung zu n8n erfolgreich! Webhook ist aktiv und antwortet.'
    }
  };
}

// =========================================================================
// 👥 BENUTZER-TABELLE (Proof of Principle)
// Hier können Benutzer, PINs, NFC/QR-IDs und API-Keys direkt gepflegt werden:
// =========================================================================
const USERS_DB = [
  {
    id: 'tzobel',
    name: 'Dr. Thomas Zobel',
    badge_id: 'USER001',                   // NFC-UID oder QR-Code (z.B. USER001)
    pin: '1234',                          // 4-stellige PIN
    elab_api_key: 'DEIN_ELABFTW_API_KEY', // eLabFTW API Key dieses Benutzers
    elab_host: 'https://elab.uni-muenster.de',
    unigpt_api_key: ''                    // Optional: falls eigener uniGPT Key
  },
  {
    id: 'mmustermann',
    name: 'Max Mustermann',
    badge_id: 'USER002',
    pin: '0000',
    elab_api_key: 'MAX_ELABFTW_API_KEY',
    elab_host: 'https://elab.uni-muenster.de',
    unigpt_api_key: ''
  },
  {
    id: 'lab_guest',
    name: 'Gastforscher / Praktikant',
    badge_id: 'GUEST01',
    pin: '9999',
    elab_api_key: 'GUEST_ELABFTW_API_KEY',
    elab_host: 'https://elab.uni-muenster.de',
    unigpt_api_key: ''
  }
];

// =========================================================================
// 🧪 eLabFTW TEMPLATE HUB PROXY / MOCK
// =========================================================================
const ELAB_TEMPLATES_CATALOG = [
  {
    id: 101,
    title: 'Standard Mikroskopie Protokoll (eLabFTW)',
    category: 'Microscopy',
    description: 'Offizielle Institutsvorlage für Konfokalmikroskopie & Bildaufnahme',
    metadata: {
      extra_fields: {
        'Mikroskop': { type: 'select', options: ['Zeiss LSM 980', 'Leica SP8', 'Olympus SpinSR'], required: true },
        'Objektiv': { type: 'select', options: ['20x Luft', '40x Öl', '63x Öl Plan-Apo'], required: true },
        'Laser-Wellenlänge': { type: 'text', description: 'z.B. 405nm, 488nm, 561nm', required: true },
        'Fluorophore': { type: 'text', description: 'DAPI, GFP, mCherry etc.' },
        'Immersionsöl': { type: 'checkbox', value: true },
        'Proben-ID': { type: 'text', required: true }
      }
    }
  },
  {
    id: 102,
    title: 'Live-Cell Imaging (eLabFTW)',
    category: 'Live Cell',
    description: 'Langzeit-Messung mit Klimakammer & CO2-Kontrolle',
    metadata: {
      extra_fields: {
        'Zelllinie': { type: 'text', required: true },
        'Passage': { type: 'number', required: false },
        'Temperatur (°C)': { type: 'number', value: 37, required: true },
        'CO2 Gehalt (%)': { type: 'number', value: 5, required: true },
        'Intervall (min)': { type: 'number', value: 10, required: true },
        'Gesamtdauer (h)': { type: 'number', value: 24, required: true }
      }
    }
  },
  {
    id: 103,
    title: 'Antikörper Färbung & Immunfluoreszenz (eLabFTW)',
    category: 'Histology',
    description: 'Standard-Färbeprotokoll für Gewebeschnitte',
    metadata: {
      extra_fields: {
        'Primärantikörper': { type: 'text', required: true },
        'Verdünnung Primär': { type: 'text', value: '1:500' },
        'Sekundärantikörper': { type: 'text', required: true },
        'Verdünnung Sekundär': { type: 'text', value: '1:1000' },
        'Inkubationszeit': { type: 'text', value: 'Overnight 4°C' }
      }
    }
  },
  {
    id: 104,
    title: 'Molekularbiologie: PCR & Gelelektrophorese (eLabFTW)',
    category: 'General',
    description: 'Standard-PCR Protokoll mit Annealing-Temperatur und Zyklenzahl',
    metadata: {
      extra_fields: {
        'Target-Gen': { type: 'text', required: true },
        'Primer Vorwärts': { type: 'text', required: true },
        'Primer Rückwärts': { type: 'text', required: true },
        'Annealing Temperatur (°C)': { type: 'number', value: 58, required: true },
        'Zyklenzahl': { type: 'number', value: 35, required: true },
        'Polymerase': { type: 'select', options: ['Phusion High-Fidelity', 'Taq Standard', 'Q5 Hot Start'] }
      }
    }
  }
];

if (action === 'get_elabftw_templates') {
  return {
    json: {
      is_login: true,
      status: 'success',
      templates: ELAB_TEMPLATES_CATALOG
    }
  };
}

if (action === 'get_elabftw_template_details') {
  const tplId = body.templateId;
  const found = ELAB_TEMPLATES_CATALOG.find(t => String(t.id) === String(tplId));
  return {
    json: {
      is_login: true,
      status: 'success',
      template: found || null
    }
  };
}

// Helper: Suche User STRENG nach physischer Badge-ID (NFC/QR)
function findUserByBadge(badgeQuery) {
  if (!badgeQuery) return null;
  const q = String(badgeQuery).trim().toLowerCase();
  return USERS_DB.find(u => u.badge_id && u.badge_id.toLowerCase() === q) || null;
}

// 1. FALL: Login-Anfrage aus der PWA (Zwingend NFC-Tag / QR-Code + PIN)
if (action === 'login') {
  const badgeId = body.identifier || body.badge_id || '';
  const pin = String(body.pin || '').trim();
  const user = findUserByBadge(badgeId);

  if (!user) {
    return {
      json: {
        is_login: true,
        status: 'error',
        authenticated: false,
        message: `NFC/QR-Ausweis „${badgeId}“ nicht registriert. Bitte physischen NFC-Chip oder QR-Code scannen.`
      }
    };
  }

  if (user.pin !== pin) {
    return {
      json: {
        is_login: true,
        status: 'error',
        authenticated: false,
        message: 'Falsche PIN. Bitte erneut versuchen.'
      }
    };
  }

  // Erfolgreich authentifiziert!
  return {
    json: {
      is_login: true,
      status: 'success',
      authenticated: true,
      message: `Willkommen, ${user.name}! Authentifizierung erfolgreich.`,
      user: {
        id: user.id,
        name: user.name,
        badge_id: user.badge_id
      }
    }
  };
}

// 2. FALL: Reguläre Aktion (direct, ai_assistant, approve_and_create)
const auth = body.auth || {};
const authId = auth.userId || body.userId;
const authBadge = auth.badge_id;
const authPin = String(auth.pin || '').trim();
const user = USERS_DB.find(u => 
  (authBadge && u.badge_id && u.badge_id.toLowerCase() === String(authBadge).toLowerCase()) ||
  (authId && u.id.toLowerCase() === String(authId).toLowerCase())
);

if (!user || user.pin !== authPin) {
  return {
    json: {
      is_auth_error: true,
      status: 'error',
      authenticated: false,
      message: 'Authentifizierung fehlgeschlagen: Bitte per NFC/QR-Ausweis am Terminal anmelden.'
    }
  };
}

// Gültiger Benutzer: Seine API Keys in den n8n-Workflow einbetten!
return {
  json: {
    is_login: false,
    is_auth_error: false,
    ...body,
    user: {
      id: user.id,
      name: user.name,
      badge_id: user.badge_id
    },
    elab_api_key: user.elab_api_key || '',
    elab_host: user.elab_host || 'https://elab.uni-muenster.de',
    unigpt_api_key: user.unigpt_api_key || ''
  }
};

const body = $input.first().json;
const meta = body.metadata || {};
const template = body.template || {};
const templateFields = Array.isArray(template.fields) ? template.fields : [];
const fieldMap = new Map(templateFields.map(f => [f.key, f]));
const templateName = template.name || 'Standard Messung';
const note = body.general_note || '';
const integrations = body.integrations || {};
const action = body.action || 'direct';
const user = body.user || { name: 'Unbekannter Nutzer', id: 'terminal' };

const isElabActive = integrations.elabftw !== false;

const dateStr = new Date().toLocaleDateString('de-DE');
const title = `[MetaFold] ${templateName} - ${user.name} - ${dateStr}`;

// Helper: Convert metadata to elabFTW extra_fields format
function buildElabMetadata(metadataObj, fieldsArray) {
  const fMap = new Map(fieldsArray.map(f => [f.key, f]));
  const extra_fields = {};
  let pos = 1;

  for (const [key, val] of Object.entries(metadataObj)) {
    if (val === '' || val === null || val === undefined || (Array.isArray(val) && val.length === 0)) continue;

    const fDef = fMap.get(key);
    const label = fDef?.label || key;
    const fType = fDef?.type || (typeof val === 'boolean' ? 'checkbox' : typeof val === 'number' ? 'number' : 'text');

    let elabType = 'text';
    if (fType === 'select' || fType === 'dropdown') elabType = 'select';
    else if (fType === 'checkbox') elabType = 'checkbox';
    else if (fType === 'number') elabType = 'number';
    else if (fType === 'date') elabType = 'date';
    else elabType = 'text';

    let elabVal = val;
    if (elabType === 'checkbox') {
      elabVal = (val === true || val === 'true' || val === 'on' || val === 'Ja' || val === 'yes') ? 'on' : '';
    } else if (Array.isArray(val)) {
      elabVal = val.join(', ');
    } else {
      elabVal = String(val);
    }

    const fieldObj = {
      type: elabType,
      value: elabVal,
      position: pos++
    };

    if (fDef?.description) fieldObj.description = fDef.description;
    if (fDef?.options && elabType === 'select') {
      fieldObj.options = fDef.options.map(String);
    }

    extra_fields[label] = fieldObj;
  }

  return {
    extra_fields,
    elabftw: { display_main_text: true }
  };
}

const directElabMetadata = buildElabMetadata(meta, templateFields);

let rowsHtml = '';
for (const [key, val] of Object.entries(meta)) {
  if (val !== '' && val !== null && val !== undefined && (!Array.isArray(val) || val.length > 0)) {
    const fDef = fieldMap.get(key);
    const label = fDef?.label || key;
    const displayVal = Array.isArray(val) ? val.join(', ') : val;
    rowsHtml += `<tr><td style="font-weight:600; padding:6px 10px; border:1px solid #e2e8f0; background:#f8fafc;">${label}</td><td style="padding:6px 10px; border:1px solid #e2e8f0;">${displayVal}</td></tr>`;
  }
}

const bodyHtml = `
  <h3 style="color:#0f172a; margin-bottom:6px;">📋 MetaFold Metadaten</h3>
  <div style="font-size:12px; color:#334155; margin-bottom:12px; background:#f1f5f9; padding:8px 12px; border-radius:6px; border-left:4px solid #3b82f6;">
    👤 <b>Erfasst von:</b> ${user.name} <i>(ID: ${user.id})</i>
  </div>
  <table style="border-collapse:collapse; width:100%; font-family:system-ui,sans-serif; font-size:13px; margin-bottom:16px;">
    <thead><tr style="background:#e2e8f0;"><th style="padding:8px 10px; text-align:left; border:1px solid #cbd5e1;">Parameter</th><th style="padding:8px 10px; text-align:left; border:1px solid #cbd5e1;">Wert</th></tr></thead>
    <tbody>${rowsHtml || '<tr><td colspan="2" style="padding:8px; color:#64748b;">Keine Metadatenfelder belegt.</td></tr>'}</tbody>
  </table>
  ${note ? `<h4 style="color:#0f172a; margin-bottom:4px;">🎙️ Diktierte Sprachnotiz</h4><div style="background:#eff6ff; border-left:4px solid #3b82f6; padding:10px 14px; border-radius:4px; font-size:13px; color:#1e3a8a;">${note.replace(/\n/g, '<br>')}</div>` : ''}
  <hr style="margin-top:24px; border:0; border-top:1px solid #e2e8f0;">
  <p style="font-size:11px; color:#94a3b8;">Automatisch erfasst via MetaFold Mobile Terminal am ${new Date().toLocaleString('de-DE')}</p>
`;

// LLM System Prompt für fachliche Kuration & Entwurf
const systemPrompt = `Du bist ein erfahrener wissenschaftlicher Labor- und Datenkurator für das MetaFold Metadaten-System im Bereich der biologischen und medizinischen Forschung (Grundlagenforschung, Modellorganismen wie z. B. Drosophila, Zebrafisch, C. elegans, Nagetiere, Zell- und Gewebekulturen, Mikroskopie & Bildgebung, Molekularbiologie und Biochemie).\nDeine Aufgabe ist es, aus den eingegebenen Metadaten ("current_metadata"), der Liste erlaubter Template-Felder ("allowed_fields") und der gesprochenen Sprachnotiz ("voice_note") einen professionell aufbereiteten, konsistenten und wissenschaftlich sauberen Labor-Entwurf zu erstellen.\n\n### REGELN:\n\n1. ANTWORTFORMAT:\n   - Antworte AUSSCHLIESSLICH mit einem validen JSON-Objekt.\n   - Kein Markdown, keine Backticks (kein \`\`\`json), kein Text davor oder danach.\n   - Das JSON-Objekt MUSS exakt folgende Struktur haben:\n     {\n       "title": "<Experimenttitel>",\n       "metadata": { ... },\n       "additional_notes": "<Aufbereitete Notizen>"\n     }\n\n2. INTELLIGENTE FEHLERKORREKTUR & BIOLOGISCHER FACHKONTEXT:\n   - Handle als intelligenter wissenschaftlicher Editor, NICHT als stummer Abschreiber.\n   - Korrigiere aktiv und selbstständig Tippfehler, Spracherkennungsfehler (Whisper/STT) und phonetische Ungenauigkeiten sowohl in "current_metadata" als auch in der Notiz:\n     * Modellorganismen & Taxonomie: "Drosophyla" -> "Drosophila melanogaster", "Danio" -> "Danio rerio", etc.\n     * Anatomie & Proben: "Eggk chamber" -> "Egg chamber", "imaginal disk" -> "imaginal disc", "somites", "blastula", etc.\n     * Methoden & Parameter: "resonant Scanner" -> "Resonant Scanner", "clsm" -> "CLSM", "40x oil" -> "40x Oil", "paraformaldehyd" -> "Paraformaldehyd (PFA)".\n\n3. WISSENSCHAFTLICHE STANDARDISIERUNG & NOMENKLATUR:\n   - Antikörper: Einheitlich nach wissenschaftlicher Nomenklatur formatieren: [Wirtsorganismus] anti-[Target] [Fluorophor/Konjugat] (z. B. "Mouse anti-Tubulin", "Rabbit anti-GFP", "Goat anti-Mouse Alexa Fluor 488").\n   - Fluorophore & Farbstoffe: Etablierte Standardbezeichnungen nutzen (z. B. "Alexa Fluor 488" statt "Alexa 488", "DAPI", "Hoechst 33342", "mCherry", "EGFP", "Phalloidin-TRITC").\n   - Einheiten & Maße normieren (z. B. "534 nm", "100 ms", "µm", "°C").\n\n4. REGELN FÜR "metadata":\n   - Mappe relevante Fakten aus der Notiz in existierende Template-Felder (z. B. "normalen clsm Modus" -> mode: "Normal").\n   - Hat ein Template-Feld feste Optionen ("options"), wähle exakt den passenden hinterlegten Optionswert.\n   - Falls in der Notiz neue Parameter mit klarer Key-Value-Logik genannt werden, für die es kein passendes Template-Feld gibt (z. B. spezifische Laserlinie "534 nm" beim Weißlichtlaser oder ein spezielles Filterset), kannst du hierfür einen prägnanten neuen Key in "metadata" anlegen (z. B. "laser_wavelength": "534 nm").\n\n5. REGELN FÜR "additional_notes" (GUT LESBARER FLIESSTEXT, KEINE STUMPFE DOPPELUNG):\n   - KEINE STUMPFEN DOPPELUNGEN: Zähle nicht einfach Metadatenfelder als isolierte Liste erneut auf, wenn sie bereits im Metadaten-Block stehen.\n   - KONTEXT IST ERLAUBT: Wenn ein Parameter im Zusammenhang einer zusammenhängenden Versuchsbeschreibung, Beobachtung oder Begründung Sinn ergibt (z. B. "Da das Signal schwach war, wurde der CLSM-Modus mit 534 nm gewählt..."), darf er natürlich flüssig und lesbar im Text verbleiben.\n   - FLIESSTEXT & FORM: Formuliere die Notiz – je nach Art der Spracheingabe – als gut lesbaren, sachlichen Fließtext oder prägnanten Absatz. Entferne mündliche Füllwörter und Floskeln ("weiß nicht", "ähm", "also", "glaube ich").\n   - Falls alle Inhalte der Sprachnotiz bereits vollständig in den Metadatenfeldern abgebildet sind und keine weiteren Notizen oder Beobachtungen vorliegen, gib "" zurück.\n\n6. TITEL ("title"):\n   - FALLS EIN TITEL MITGELIEFERT WIRD: Wenn bereits ein Titel im Input (oder Template) übergeben wird ("current_title") und dieser nicht leer ist, behalte diesen bei (und korrigiere allenfalls offensichtliche Tippfehler).\n   - FALLS KEIN TITEL VORHANDEN IST: Generiere nur dann einen neuen, prägnanten Titel basierend auf Organismus, Probe, Marker oder Methode (z. B. "Confocal imaging of Drosophila egg chamber").`;

const userPromptObj = {
  template: {
    id: template.id || '',
    name: templateName,
    category: template.category || '',
    allowed_fields: templateFields.map(f => ({
      key: f.key,
      label: f.label || f.key,
      type: f.type || 'text',
      options: f.options || [],
      description: f.description || ''
    }))
  },
  current_title: body.title || '',
  current_metadata: meta,
  voice_note: note
};

const llmRequest = {
  model: 'Qwen3.8-27B',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: JSON.stringify(userPromptObj) }
  ],
  temperature: 0.1,
  max_tokens: 800
};

return {
  json: {
    action: action,
    is_elab_active: isElabActive,
    template_name: templateName,
    user: user,
    elab_api_key: body.elab_api_key || '',
    elab_host: body.elab_host || 'https://elab.uni-muenster.de',
    unigpt_api_key: body.unigpt_api_key || '',
    elab_payload: {
      title: title,
      body: bodyHtml,
      metadata: JSON.stringify(directElabMetadata)
    },
    direct_metadata_obj: directElabMetadata,
    llm_request: llmRequest,
    ai_draft_input: body.ai_draft || null,
    original_body: body
  }
};

const llmRes = $input.first().json;
const raw = llmRes.choices?.[0]?.message?.content || '';
let draft = null;

try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  draft = JSON.parse(cleaned);
} catch (e) {
  draft = null;
}

const prep = $('Prepare Payload & HTML').item.json;
const origBody = prep.original_body || {};
const origMeta = origBody.metadata || {};
const templateFields = origBody.template?.fields || [];
const allowedKeys = new Set(templateFields.map(f => f.key));

let cleanedMetadata = {};
if (draft && typeof draft.metadata === 'object' && draft.metadata !== null) {
  for (const [k, v] of Object.entries(draft.metadata)) {
    if (allowedKeys.size === 0 || allowedKeys.has(k) || (v !== '' && v !== null && v !== undefined && typeof v !== 'object')) {
      cleanedMetadata[k] = v;
    }
  }
  for (const [k, v] of Object.entries(origMeta)) {
    if (cleanedMetadata[k] === undefined && v !== '' && v !== null && v !== undefined) {
      cleanedMetadata[k] = v;
    }
  }
} else {
  cleanedMetadata = { ...origMeta };
}

const finalTitle = (draft && draft.title) ? draft.title : (origBody.title || prep.elab_payload.title);
const finalNotes = (draft && (draft.additional_notes || draft.notes || draft.text)) ? (draft.additional_notes || draft.notes || draft.text) : (origBody.general_note || '');

return {
  json: {
    status: 'ai_draft',
    ai_draft: {
      title: finalTitle,
      metadata: cleanedMetadata,
      additional_notes: finalNotes
    }
  }
};

const prep = $json;
const body = prep.original_body || {};
const draft = body.ai_draft || prep.ai_draft_input || {};
const meta = (draft.metadata && typeof draft.metadata === 'object') ? draft.metadata : (body.metadata || {});
const template = body.template || {};
const templateFields = Array.isArray(template.fields) ? template.fields : [];
const fieldMap = new Map(templateFields.map(f => [f.key, f]));
const user = prep.user || { name: 'Unbekannter Nutzer', id: 'terminal' };

const finalTitle = draft.title || prep.elab_payload.title;
const additionalNotes = draft.additional_notes || draft.notes || draft.text || '';

// Extra Fields for eLabFTW
const extra_fields = {};
let pos = 1;

for (const [key, val] of Object.entries(meta)) {
  if (val === '' || val === null || val === undefined || (Array.isArray(val) && val.length === 0)) continue;

  const fDef = fieldMap.get(key);
  const label = fDef?.label || key;
  const fType = fDef?.type || (typeof val === 'boolean' ? 'checkbox' : typeof val === 'number' ? 'number' : 'text');

  let elabType = 'text';
  if (fType === 'select' || fType === 'dropdown') elabType = 'select';
  else if (fType === 'checkbox') elabType = 'checkbox';
  else if (fType === 'number') elabType = 'number';
  else if (fType === 'date') elabType = 'date';
  else elabType = 'text';

  let elabVal = val;
  if (elabType === 'checkbox') {
    elabVal = (val === true || val === 'true' || val === 'on' || val === 'Ja' || val === 'yes') ? 'on' : '';
  } else if (Array.isArray(val)) {
    elabVal = val.join(', ');
  } else {
    elabVal = String(val);
  }

  const fieldObj = {
    type: elabType,
    value: elabVal,
    position: pos++
  };

  if (fDef?.description) fieldObj.description = fDef.description;
  if (fDef?.options && elabType === 'select') {
    fieldObj.options = fDef.options.map(String);
  }

  extra_fields[label] = fieldObj;
}

const elabftwMetadata = {
  extra_fields: extra_fields,
  elabftw: {
    display_main_text: true
  }
};

let rowsHtml = '';
for (const [key, val] of Object.entries(meta)) {
  if (val !== '' && val !== null && val !== undefined && (!Array.isArray(val) || val.length > 0)) {
    const fDef = fieldMap.get(key);
    const label = fDef?.label || key;
    const displayVal = Array.isArray(val) ? val.join(', ') : val;
    rowsHtml += `<tr><td style="font-weight:600; padding:6px 10px; border:1px solid #e2e8f0; background:#f8fafc;">${label}</td><td style="padding:6px 10px; border:1px solid #e2e8f0;">${displayVal}</td></tr>`;
  }
}

const finalBodyHtml = `
  <h3 style="color:#0f172a; margin-bottom:6px;">📋 MetaFold Laborbericht (KI-geprüft & freigegeben)</h3>
  <div style="font-size:12px; color:#334155; margin-bottom:12px; background:#f1f5f9; padding:8px 12px; border-radius:6px; border-left:4px solid #3b82f6;">
    👤 <b>Erfasst von:</b> ${user.name} <i>(ID: ${user.id})</i>
  </div>
  <table style="border-collapse:collapse; width:100%; font-family:system-ui,sans-serif; font-size:13px; margin-bottom:16px;">
    <thead><tr style="background:#e2e8f0;"><th style="padding:8px 10px; text-align:left; border:1px solid #cbd5e1;">Parameter</th><th style="padding:8px 10px; text-align:left; border:1px solid #cbd5e1;">Wert</th></tr></thead>
    <tbody>${rowsHtml || '<tr><td colspan="2" style="padding:8px; color:#64748b;">Keine Metadatenfelder belegt.</td></tr>'}</tbody>
  </table>
